# -*- coding: utf-8 -*-
"""Bengali text for the Rule page. TEXT = {key: translated inner HTML}."""
TEXT = {
"k34706326": "প্রার্থনার নিয়ম সম্বন্ধে",
"kc1ba8633": "কতটা প্রার্থনা করতে হবে, এবং যে যতটুকু পারে সেই অনুসারে প্রার্থনা করার বিষয়ে মণ্ডলীর উৎসগুলি যা বলে। এই পৃষ্ঠা সেই উৎসগুলিই তুলে ধরে; তাদের সঙ্গে উপদেশ যোগ করে না।",
"ka7965ff8": "<strong>প্রথমে এটি পড়ুন।</strong> Plithos-এ যা কিছু আছে তা তথ্যসূত্র, আপনাকে মাপার মানদণ্ড নয়। প্রার্থনা, উপবাসের নিয়ম, প্রহর এবং উপাসনার ক্রম এখানে সম্পূর্ণ দেওয়া হয়েছে, কারণ সেগুলি মণ্ডলীর উত্তরাধিকার এবং সকলের নাগালে থাকা উচিত। সম্পূর্ণ দেওয়া মানে এই নয় যে কারও তা সবটুকু পালন করতেই হবে।",
"kef5c7431": "আপনি যে নিয়ম পালন করেন তা আপনার আধ্যাত্মিক পিতা আপনার জ্ঞান, আপনার সামর্থ্য ও আপনার পরিস্থিতি অনুসারে স্থির করেন। এই সাইটের কোনো কিছুই তার উপরে যায় না, এবং যিনি মুদ্রিত অংশের চেয়ে কম প্রার্থনা করেন তাঁর উপরে এখানে কোনো বিচার নেই। যিনি দিনে তিনবার প্রভুর প্রার্থনা মন থেকে বলেন, তিনি সেই নিয়মই পালন করছেন যা মণ্ডলী প্রথম শতাব্দীতে দিয়েছিল।",
"kfd250c56": "এই পৃষ্ঠা উৎসগুলি যা বলে তা তুলে ধরে, নিজের উপদেশ যোগ করে না। যেখানে কোনো বাক্যে সূত্র নেই, সেখানে তা এই সাইট সম্পর্কে বক্তব্য, আপনার প্রার্থনার নির্দেশ নয়। পরিচালনা আপনার পুরোহিতের, যিনি আপনার জীবন জানেন; এই সাইট তা জানে না।",
"kd06d4f8a": "প্রাচীনতম নিয়ম আসলে কী ছিল",
"kc90dad01": "টিকে থাকা প্রাচীনতম খ্রিষ্টীয় আচরণ-পুস্তিকা হল দিদাখে, আনুমানিক ১০০ খ্রিষ্টাব্দের। তার প্রার্থনার নিয়ম হল দিনে তিনবার প্রভুর প্রার্থনা।",
"kadda83fe": "দিনে তিনবার এইভাবে প্রার্থনা করো।",
"k513c7122": "দিদাখে ৮ &middot; অনু. M. B. Riddle, ১৮৮৬ &middot; <a href=\"/library#work=didache\">গ্রন্থাগারে পড়ুন</a>",
"k355facce": "সেই একই রচনা, দুই অধ্যায় আগে, পরিমাণের নীতি সরাসরি বলে, এবং এটি আধুনিক শিথিলতা নয় বরং এই বিষয়ে মণ্ডলীর লেখা প্রাচীনতম কথা:",
"k0133b448": "কেননা তুমি যদি প্রভুর সমস্ত জোয়াল বহন করতে পারো, তবে তুমি সিদ্ধ হবে; কিন্তু যদি না পারো, তবে যা পারো তাই করো।",
"kec4ccf0b": "দিদাখে ৬ &middot; অনু. M. B. Riddle, ১৮৮৬ &middot; <a href=\"/library#work=didache\">গ্রন্থাগারে পড়ুন</a>",
"ka800cdac": "পরবর্তী প্রার্থনা-পুস্তকের পূর্ণতর প্রার্থনা-ক্রম এর পরে গড়ে উঠেছে। দিদাখে কেবল সেই প্রাচীনতম লিখিত নিয়ম যা মণ্ডলীর কাছে আছে, এবং তা এটুকুই দাবি করে।",
"kc8529ac1": "পরিমাণই মাপকাঠি নয়",
"k605c07f5": "সন্ত জন কাসিয়ান, পঞ্চম শতাব্দীর গোড়ায় মিশরীয় পিতাদের শিক্ষা লিপিবদ্ধ করে, প্রার্থনার জন্য বিশেষভাবে আলাদা করে রাখা সময় দিয়ে প্রার্থনা গোনার বিরুদ্ধে সতর্ক করেন:",
"kda219ca8": "কারণ সে অতি অল্পই প্রার্থনা করে, যে কেবল সেই সময়েই প্রার্থনা করতে অভ্যস্ত যখন সে হাঁটু পাতে।",
"k87ef1fff": "সন্ত জন কাসিয়ান, আলাপন ১০.১৪ &middot; অনু. Edgar C. S. Gibson &middot; <a href=\"/library#work=cassian-conferences\">গ্রন্থাগারে পড়ুন</a>",
"k6f06dcb5": "সুতরাং কাসিয়ানের কাছে প্রার্থনার মাপ নির্দিষ্ট সময়ের চেয়ে প্রশস্ত, এবং কথাটি তাঁদের উদ্দেশে যাঁরা তাকে সেই সময়ের মধ্যে আবদ্ধ করেন। এই ভাবনা তিনি আনেননি। প্রেরিত আগেই নিয়মটি এমন রূপে দিয়েছিলেন যা কোনো ঘড়ি ধরে রাখতে পারে না:",
"k9d16dd79": "সর্বদা সমস্ত প্রকার প্রার্থনা ও বিনতি সহকারে আত্মায় প্রার্থনা করো, এবং সেই উদ্দেশ্যেই সমস্ত অধ্যবসায় ও বিনতি সহকারে সকল পবিত্রজনের জন্য জাগিয়া থাকো;",
"kd45e4afe": "ইফিষীয় ৬:১৮",
"k8ff6957a": "আরও সংক্ষেপে: <em>অবিরত প্রার্থনা করো</em> (১ থিষলনীকীয় ৫:১৭)। নির্দিষ্ট সময়ের নিয়ম তারই সেবা করে; তাকে নিঃশেষ করে না।",
"k94022491": "এটি একটি ক্রম, সিঁড়ি নয়",
"k6f5ac9c2": "যা অনুসরণ করছে তা Plithos-এর নির্ধারিত ধাপ নয়। এটি উৎস ও গৃহীত গ্রন্থে যা আছে তার একটি ক্রম, দিনের কতটুকু প্রত্যেকটি চায় সেই অনুসারে সাজানো। <strong>এর মধ্যে কোনটি কোনো নির্দিষ্ট মানুষের জন্য প্রযোজ্য, তা তাঁর আধ্যাত্মিক পিতার প্রশ্ন, এই পৃষ্ঠার নয়।</strong>",
"kbd0070ec": "এটি সিঁড়ি নয়, আর প্রথম ভুক্তিটিই তার কারণ। যিশু-প্রার্থনা প্রথমে আছে কারণ তা মানুষের পরিস্থিতির কাছ থেকে সবচেয়ে কম চায়, এই কারণে নয় যে তা মানুষের কাছ থেকে সবচেয়ে কম চায়। সেই একই প্রার্থনাকেই নীরবতার পিতারা সমগ্র প্রার্থনা বলে বর্ণনা করেন, এবং যাঁরা বহু দূর এগিয়েছেন তাঁদের লিখিত সবকিছুর পরিবর্তে সেটিই দেওয়া হয়। তা একই সঙ্গে দুই প্রান্তে দাঁড়িয়ে আছে।",
"kec53651e": "যিশু-প্রার্থনা",
"kd76e85df": "যখন সময় নেই, বই নেই, নীরবতা নেই - পথে, কাজে, অসুস্থতায়, যখন দাঁড়ানোও যায় না, উচ্চস্বরে বলাও যায় না",
"k15c8fcc6": "যিশু-প্রার্থনা তার পূর্ণ রূপে: <em>প্রভু যিশু খ্রিষ্ট, ঈশ্বরের পুত্র, আমার প্রতি, এই পাপীর প্রতি দয়া করুন।</em> যেখানে তাও বেশি, সেখানে পিতারা সংক্ষিপ্ততর রূপের অনুমতি দেন - <em>প্রভু যিশু খ্রিষ্ট, আমার প্রতি দয়া করুন</em>, অথবা কেবল <em>প্রভু, দয়া করুন</em>। এতে বই লাগে না, দাঁড়ানো লাগে না, স্বরও লাগে না, এবং একে সাধারণ কর্মদিবস জুড়ে বহন করা যায়।",
"k433c6e1a": "<a href=\"/prayers#s=heart\">যিশু-প্রার্থনা, এবং তা রক্ষার বিষয়ে পিতাদের পরামর্শ</a>",
"k0607d349": "এটি প্রথমে আসে কারণ তা সব পরিস্থিতিতেই টিকে থাকে, এই কারণে নয় যে এখানে যা আছে তার মধ্যে এটিই ক্ষুদ্রতম। কাসিয়ান, আলাপন ১০.১৪: \"সে অতি অল্পই প্রার্থনা করে, যে কেবল সেই সময়েই প্রার্থনা করতে অভ্যস্ত যখন সে হাঁটু পাতে।\"",
"k4fbd7571": "প্রভুর প্রার্থনা, দিনে তিনবার",
"kccf34183": "সম্ভব হলে, নির্দিষ্ট সময়ে নির্দিষ্ট নিয়ম",
"k6c98a369": "আমাদের কাছে থাকা প্রাচীনতম খ্রিষ্টীয় পুস্তিকার নিয়ম। ছোট নিয়ম, কিন্তু নির্দিষ্ট সময়ের নিয়ম, আর তাই ভাঙা দিনের কাছ থেকে যিশু-প্রার্থনার চেয়ে বেশি চায়।",
"kb80095bf": "দিদাখে ৮।",
"k73f947ac": "সারভের সন্ত সেরাফিমের নিয়ম",
"kbeb11458": "যাঁদের কাজ দীর্ঘতর নিয়মের জায়গা রাখে না তাঁদের জন্য",
"kba90cd4c": "উঠে, প্রতিমাগুলির সামনে দাঁড়িয়ে: প্রভুর প্রার্থনা তিনবার, <em>হে কুমারী ঈশ্বরজননী, আনন্দিত হও</em> তিনবার, এবং বিশ্বাস-সূত্র একবার। তারপর কাজে গিয়ে, সারা সকাল চুপে চুপে যিশু-প্রার্থনা বলতে বলতে, আর দুপুরের পর <em>হে পরম পবিত্র ঈশ্বরজননী, আমাকে রক্ষা করো</em>। ঘুমের আগে আবার সেই একই সংক্ষিপ্ত নিয়ম।",
"k6464f90a": "সন্ত সেরাফিম এটি দিয়েছিলেন সেই শ্রমজীবী ও গৃহস্থদের, যাঁরা পূর্ণতর সকাল ও সন্ধ্যার প্রার্থনা পালন করতে পারতেন না, এবং তিনি একে এমন ছাড় বলে গণ্য করেননি যা থেকে বেড়ে উঠে বেরিয়ে যেতে হয়। এটি নির্দিষ্ট সময়ের নির্দিষ্ট প্রার্থনার নিয়ম, কর্মদিবস জুড়ে চলা এক প্রার্থনার সঙ্গে যুক্ত, আর সেই কারণেই এটি এখানে, আরও নিচে নয়।",
"kc823332f": "সারভের সন্ত সেরাফিম, সাধারণ বিশ্বাসীদের প্রতি তাঁর উপদেশে। প্রার্থনাগুলি নিজেই প্রার্থনার পৃষ্ঠায় আছে।",
"k3041ac63": "সকাল ও সন্ধ্যা",
"k225e3ccd": "সাধারণ বিশ্বাসীর জন্য প্রার্থনা-পুস্তকের প্রচলিত নিয়ম",
"kf4d2a2e5": "ওঠার সময় সকালের প্রার্থনা এবং ঘুমের আগে সন্ধ্যার প্রার্থনা, মনোযোগ দিয়ে বলা, তাড়াহুড়ো করে নয়।",
"k98ad4446": "<a href=\"/prayers#s=daily\">সকাল ও সন্ধ্যার প্রার্থনা</a>",
"k8ad36869": "নির্জনবাসী সন্ত থেওফান প্রার্থনা-পুস্তকের সকাল ও সন্ধ্যার প্রার্থনাকে সদ্য শুরু করা বিশ্বাসীর জন্য সম্পূর্ণ যথেষ্ট মনে করতেন। পূর্ণতর পরামর্শের জন্য প্রার্থনার পৃষ্ঠার টীকা দেখুন।",
"k4cecadd4": "প্রহরগুলির সঙ্গে",
"kefb7d0a1": "যেখানে দিন তা অনুমতি দেয়",
"k8fb45542": "দিনভর সংক্ষিপ্ত উপাসনা, প্রথম প্রহর থেকে রাত্রি-প্রার্থনা পর্যন্ত।",
"k6b300612": "<a href=\"/prayers#s=hours\">প্রহরগুলি</a>",
"k61610f0a": "দিদাখের তিনটি দৈনিক প্রার্থনাই এই চক্রের বীজ। পূর্ণ প্রহরগুলি হোরোলোগিওনে দেওয়া আছে।",
"kb3c5ab3d": "প্রভুভোজের প্রস্তুতি",
"k8dbdf873": "রহস্যগুলি গ্রহণের আগে",
"kced3fbfd": "প্রস্তুতির ক্রম, পানপাত্রের সামনে বলা দুটি প্রার্থনা, এবং তার পরের ধন্যবাদ। ক্রমের কতটা বলা হয়, এবং তা আগের সন্ধ্যায় পালিত হয় না সেই সকালে, তা ঐতিহ্য অনুসারে ভিন্ন এবং আধ্যাত্মিক পিতা স্থির করেন। পিতারা কাছে আসার প্রকৃত শর্ত কী মনে করেন, তা নিচে দেখুন।",
"k8f37e928": "<a href=\"/prayers#s=communion\">পবিত্র প্রভুভোজের প্রার্থনা, তিনটি অংশে</a>",
"k88dda4ec": "স্লাভ ও গ্রিক ঐতিহ্যের মধ্যে চর্চা স্পষ্টভাবে ভিন্ন, প্রত্যাশিত প্রস্তুতিতেও এবং বিশ্বাসীরা কত ঘন ঘন গ্রহণ করেন তাতেও।",
"ka6cba0b8": "যখন আপনি আপনার নিয়ম পালন করতে পারেন না",
"k87db3602": "ভ্রমণ, অসুস্থতা, রাতের কাজ, ছোট সন্তান, শোক ও ক্লান্তি - এ সবই নিয়ম ভেঙে দেয়। উপরের লেখাগুলির মধ্যে দুটি সরাসরি এর সঙ্গে সম্পর্কিত।",
"k8dcf4ab6": "<strong>দিদাখে নিয়মকে সব-অথবা-কিছুই-না হিসাবে উপস্থাপন করে না।</strong> তার নির্দেশ এই নয় যে সমস্ত জোয়াল বহন করো নয়তো কিছুই নয়, বরং এই যে যেখানে সমস্তটা বহন করা যায় না, সেখানে \"যা পারো তাই করো\"।",
"ka4ac033d": "<strong>প্রার্থনা দাঁড়ানোর সময়ের মধ্যে আবদ্ধ নয়।</strong> উপরে কাসিয়ানের কথার শক্তি এখানেই: তিনি তাঁদের তিরস্কার করছেন যাঁরা কেবল হাঁটু পাতার সময় দিয়ে নিজেদের প্রার্থনা গোনেন, আর তা সেই সময়ের বাইরের প্রার্থনাকে হিসাবের ভিতরে আনে, বাইরে রাখে না। যিশু-প্রার্থনা তার গৃহীত সংক্ষিপ্ত রূপে বই, দেহের ভঙ্গি বা স্বর, কিছুই দাবি করে না।",
"k1c9eeaa9": "পিতারা কাছে আসার শর্ত কী মনে করেন",
"keac4f2df": "প্রস্তুতির ক্রম প্রকৃত মঙ্গল এবং প্রকৃত উত্তরাধিকার। তবে তা-ই মানুষকে গ্রহণের যোগ্য করে না। এই বিষয়ে পিতারা স্পষ্ট, এবং তাঁরা লিখছিলেন কোনো মুদ্রিত প্রস্তুতি-ক্রম থাকার বহু আগে।",
"kc356b366": "সন্ত জন ক্রিসোস্তম ইব্রীয় পত্রের উপর উপদেশ দিতে গিয়ে ঠিক এই প্রশ্নই তোলেন যে কত ঘন ঘন ও কতটা, এবং সেই ভাষায় উত্তর দিতে অস্বীকার করেন:",
"kce69ff57": "তবে কী? কাদের আমরা অনুমোদন করব? যাঁরা বছরে একবার গ্রহণ করেন? যাঁরা বহুবার গ্রহণ করেন? যাঁরা কদাচিৎ গ্রহণ করেন? না একবারের, না বহুবারের, না কদাচিতের, বরং যাঁরা শুদ্ধ বিবেক নিয়ে, শুদ্ধ হৃদয় থেকে, নিন্দাহীন জীবন নিয়ে কাছে আসেন। এমন লোকেরা অবিরত কাছে আসুক; কিন্তু যাঁরা এমন নন, তাঁরা একবারও নয়।",
"k2d880e69": "সন্ত জন ক্রিসোস্তম, ইব্রীয়ের উপর উপদেশ ১৭ &middot; অনু. Frederic Gardiner &middot; <a href=\"/library#work=chrysostom-homilies-hebrews\">গ্রন্থাগারে পড়ুন</a>",
"k3448180a": "ক্রিসোস্তম যে মানদণ্ডের নাম করেন তা বিবেকের অবস্থা। তিনি কোনো সংখ্যার নাম করেন না, না প্রভুভোজের, না আগে বলা প্রার্থনার, এবং ঘন ঘন হওয়ার প্রশ্নটিকে ভুল প্রশ্ন হিসাবে সরিয়ে রাখেন।",
"k4bc3e896": "সন্ত জন কাসিয়ান অন্য অর্ধেকটি ধরেন, এবং অধ্যায়ের শিরোনাম তা স্পষ্ট বলে: <em>যদিও আমরা স্বীকার করি যে আমরা পাপহীন হতে পারি না, তবু প্রভুর প্রভুভোজ থেকে আমাদের সরে থাকা উচিত নয়।</em>",
"k3620ced2": "তবু আমরা নিজেদের পাপী বলে স্বীকার করি বলে প্রভুর প্রভুভোজ থেকে সরে থাকা উচিত নয়, বরং আমাদের আত্মার আরোগ্য ও আমাদের অন্তরের শুদ্ধির জন্য আরও উৎসুক হয়ে তার দিকে ছুটে যাওয়া উচিত, এবং মনের নম্রতা ও বিশ্বাস নিয়ে আমাদের ক্ষতের ঔষধই খোঁজা উচিত, নিজেদের এত বড় অনুগ্রহ গ্রহণের অযোগ্য মনে করে।",
"k99dd8e07": "নতুবা আমরা বছরে একবারও যোগ্যভাবে প্রভুভোজ গ্রহণ করতে পারি না, যেমন কেউ কেউ করেন যাঁরা মঠে বাস করেন এবং স্বর্গীয় রহস্যগুলির মর্যাদা, পবিত্রতা ও মূল্যকে এমনভাবে দেখেন যে মনে করেন সন্ত ও নিষ্কলঙ্কদের ছাড়া কেউ তা গ্রহণের সাহস করা উচিত নয়, বরং এটা মনে করেন না যে সেগুলি গ্রহণের দ্বারাই আমাদের সন্ত ও শুদ্ধ করবে। এবং এর দ্বারাই তাঁরা সেই আত্মম্ভরিতা ও অহংকারে পড়েন যা তাঁরা এড়িয়ে চলছেন বলে মনে করেন, কারণ যখন তাঁরা গ্রহণ করেন, তখন নিজেদের গ্রহণের যোগ্য মনে করেন।",
"kb8b440b1": "সন্ত জন কাসিয়ান, আলাপন ২৩.২১ &middot; অনু. Edgar C. S. Gibson &middot; <a href=\"/library#work=cassian-conferences\">গ্রন্থাগারে পড়ুন</a>",
"kcab416e7": "কাসিয়ানের যুক্তি হল, অযোগ্যতার অনুভব থেকে সরে থাকাই বড় আত্মম্ভরিতা, কেননা যিনি যোগ্য না হওয়া পর্যন্ত সরে থাকেন তিনি ধরে নেন যে অন্য কোনো দিন তিনি যোগ্য হতেন। তার বিপরীতে তিনি রাখেন সেই কথা, যার জন্য তাঁর মতে রহস্যগুলি আছে: ইতিমধ্যে শুদ্ধদের জন্য পুরস্কার নয়, বরং সেই উপায় যার দ্বারা, তাঁরই ভাষায়, সেগুলি গ্রহণের দ্বারা আমাদের সন্ত ও শুদ্ধ করবে।",
"k1ceaa3c4": "মণ্ডলী প্রভুভোজ গ্রহণকারীকে নিজের সম্বন্ধে কী বলায়",
"k15496498": "এটি মান নামিয়ে আনা নয়। এটিই মান, এবং মণ্ডলী তা প্রত্যেক কাছে আসা মানুষের মুখে রাখে। পানপাত্রের সামনে সমগ্র সমাবেশের উচ্চস্বরে বলা স্বীকারোক্তি এ কথা বলে না যে যিনি বলছেন তিনি পৌঁছে গেছেন:",
"kffb87ae9": "হে প্রভু, আমি বিশ্বাস করি এবং স্বীকার করি যে তুমিই সত্যিই খ্রিষ্ট, জীবন্ত ঈশ্বরের পুত্র, যিনি পাপীদের রক্ষা করতে জগতে এসেছিলেন, যাঁদের মধ্যে আমিই প্রথম।",
"kd40a122c": "গ্রহণের আগের প্রার্থনা &middot; ১ তীমথিয় ১:১৫ অনুসারে &middot; <a href=\"/prayers#s=communion\">প্রার্থনা-পুস্তকে পড়ুন</a>",
"k91d95d94": "প্রেরিতের নিজের কথা হল <em>খ্রিষ্ট যিশু পাপীদের রক্ষা করতে জগতে এসেছিলেন, যাঁদের মধ্যে আমিই প্রধান</em>, আর মণ্ডলী তা পত্রের মধ্যেই রেখে দেয়নি। মণ্ডলী তা পানপাত্রের সামনে রেখেছে এবং প্রত্যেক গ্রহণকারীকে দিয়েছে যেন সে যেদিন গ্রহণ করে সেদিন তা প্রথম পুরুষে বলে। সন্ত তাঁরাই যাঁরা এই বাক্যটি বলেছেন এবং মন থেকে বলেছেন, তাঁরা নন যাঁরা এমন জায়গায় পৌঁছেছেন যেখানে তা আর তাঁদের ক্ষেত্রে খাটে না। অনুগ্রহ দেওয়া হয়; আমাদের কাছে যা চাওয়া হয় তা হল আমরা সাড়া দিই, আমাদের দেওয়া আজ্ঞা পালন করি, এবং পালন করতে ব্যর্থ হওয়ার পরেও সাড়া দিতে থাকি।",
"kf78cb40a": "বাস্তবে এর অর্থ কী",
"k87e5b047": "<strong>এই ক্রম বিধিগত শর্তগুলির মধ্যে নেই।</strong> মণ্ডলীর কোনো বিধিই গ্রহণের আগে তা দাবি করে না, এবং নির্দিষ্ট মুদ্রিত ধারাবাহিকতা বিধিগুলির চেয়ে পরের; তার কতটা বলা হবে তা আধ্যাত্মিক পিতা স্থির করেন।",
"k0e542bbd": "<strong>ঐতিহ্য যা সত্যিই নাম করে</strong> পানপাত্রের আগে তা হল এমন বিবেক যা অনুতাপহীন পাপে বিশ্রাম নেয় না, প্রতিবেশীর সঙ্গে শান্তি, প্রভুভোজের উপবাস, এবং স্বীকারোক্তির বিষয়ে আধ্যাত্মিক পিতার প্রতি আনুগত্য। কাসিয়ান উপরের অনুচ্ছেদে সরাসরি সেই ব্যক্তির প্রসঙ্গ ধরেন যিনি অযোগ্যতার কারণে সরে গেছেন; ক্রিসোস্তম ধরেন তাঁকে যিনি সংখ্যা দিয়ে গোনেন।",
"k21c606eb": "<strong>প্রভুভোজের উপবাস বিধিগত, প্রথাগত নয়।</strong> আফ্রিকীয় বিধিসংগ্রহ তা দাবি করত, বছরে একটিমাত্র ব্যতিক্রমের অনুমতি দিয়ে, সেই দিনে যেদিন প্রভুর ভোজ স্মরণ করা হয়:",
"k253a3d17": "যে বেদির সংস্কারগুলি উপবাসকারীদের ছাড়া আর কারও দ্বারা সম্পন্ন হবে না, কেবল প্রভুর ভোজের স্মরণের বার্ষিক একটি দিন ছাড়া; কারণ যদি কোনো প্রয়াতের, ধর্মাধ্যক্ষ হোন বা অন্য কেউ, স্মরণ দুপুরের পরে করতে হয়, তবে তা কেবল প্রার্থনা দিয়েই হোক, যদি সেবাকারীরা ইতিমধ্যে আহার করে থাকেন।",
"kb289f398": "আফ্রিকীয় বিধিসংগ্রহ (৪১৯), বিধি ৪১ &middot; অনু. Henry R. Percival, ১৯০০ &middot; <a href=\"/library#work=canons-ecumenical\">গ্রন্থাগারে পড়ুন</a>",
"kfd9e4371": "ত্রুল্লোর মহাসভা সেই বিধি গ্রহণ করে ব্যতিক্রমটি তুলে দিল:",
"k97125890": "কার্থেজ সভার একটি বিধি বলে যে বেদির পবিত্র রহস্যগুলি উপবাসকারীদের ছাড়া আর কারও দ্বারা সম্পন্ন হবে না, কেবল বছরে একটি দিন ছাড়া যেদিন প্রভুর ভোজ পালিত হয়। তখন, সম্ভবত সেই স্থানে মণ্ডলীর পক্ষে উপকারী কোনো পরিস্থিতির কারণে, পবিত্র পিতারা নিজেরাও এই ছাড় ব্যবহার করেছিলেন। কিন্তু যেহেতু কিছুই আমাদের যথাযথ পালন ত্যাগ করতে প্ররোচিত করে না, আমরা স্থির করছি যে প্রেরিতীয় ও পিতৃপরম্পরাগত ঐতিহ্য অনুসরণ করা হোক; এবং নির্ধারণ করছি যে মহা-উপবাসের শেষ সপ্তাহের পঞ্চম দিনে উপবাস ভাঙা এবং এইভাবে সমগ্র মহা-উপবাসকে অসম্মান করা উচিত নয়।",
"k5c17110d": "ত্রুল্লো, অর্থাৎ পঞ্চম-ষষ্ঠ মহাসভা (৬৯২), বিধি ২৯ &middot; অনু. Henry R. Percival, ১৯০০ &middot; <a href=\"/library#work=canons-ecumenical\">গ্রন্থাগারে পড়ুন</a>",
"k4b650236": "বিধিগুলি যা দাবি করে তা হল উপবাস। তা আগের মধ্যরাত থেকে গোনা হল সেই প্রথা যা তা বহন করে, এবং তা প্রতিটি অধিক্ষেত্রেই সাধারণ চর্চা। যেখানে উপাসনা সন্ধ্যায় হয়, যেমন পূর্ব-অভিষিক্ত দানের উপাসনা এবং যেমন হতে পারে খ্রিষ্টজন্ম, থেওফানিয়া, পবিত্র বৃহস্পতিবার ও পবিত্র শনিবারের উপাসনা, সেখানে সময়কাল ধর্মাধ্যক্ষ স্থির করেন, মধ্যরাত থেকে গোনা হয় না। যে ঔষধ নিতেই হয়, অসুস্থতা, গর্ভাবস্থা, শৈশব ও বার্ধক্য - এগুলি আধ্যাত্মিক পিতা দেখেন। জিজ্ঞাসা করা আর ছাড় পাওয়া এক নয়, এবং এর কোনোটিই পানপাত্র থেকে দূরে থাকার কারণ নয়।",
"kc182b483": "<strong>পানপাত্রের সামনে বলা দুটি প্রার্থনা</strong> - \"হে প্রভু, আমি বিশ্বাস করি এবং স্বীকার করি\" এবং \"তোমার রহস্যময় ভোজের\" - অধিকাংশ মণ্ডলীতে সমগ্র সমাবেশের সঙ্গে উচ্চস্বরে বলা হয়।",
"kaebd6892": "নিয়মগুলি রূপে সন্ন্যাসীয়; যে জীবন তারা চায় তা নয়",
"keedea2a4": "প্রার্থনা-পুস্তকে মুদ্রিত প্রায় প্রতিটি নির্দিষ্ট নিয়ম তার বর্তমান রূপ পেয়েছে কোনো মঠে, আর সেই কারণেই প্রস্তুতি এমনভাবে পড়া যেতে পারে যেন তা অন্য কাউকে উদ্দেশ করে লেখা। এই আপত্তি এত পুরোনো যে সন্ত জন ক্রিসোস্তম উত্তর দেওয়ার আগেই তা তাঁর শ্রোতাদের মুখে বসিয়ে দেন:",
"k3f765fe1": "তুমি বলবে, আমি সন্ন্যাসীদের একজন নই, আমার স্ত্রী ও সন্তান আছে এবং সংসারের ভার আছে। এই তো সব নষ্ট করেছে, তোমার এই ধারণা যে ঈশ্বরীয় শাস্ত্র পাঠ কেবল তাঁদেরই, অথচ তোমার তা তাঁদের চেয়ে অনেক বেশি প্রয়োজন। কারণ যাঁরা জগতে বাস করেন এবং প্রতিদিন আঘাত পান, তাঁদেরই ঔষধের প্রয়োজন সবচেয়ে বেশি।",
"kebad4fa3": "সন্ত জন ক্রিসোস্তম, মথির উপর উপদেশ ২ &middot; অনু. George Prevost &middot; <a href=\"/library#work=chrysostom-homilies-matthew\">গ্রন্থাগারে পড়ুন</a>",
"k5eee983b": "জীবনযাত্রা সম্বন্ধেও তিনি একই কথা বলেন, এবং তা বলেন মরুভূমিকে বিধান বানাতে অস্বীকার হিসাবে:",
"k00cd498f": "আমি বিধান করছি না যে তোমরা পর্বত ও মরুভূমি অধিকার করবে, বরং এই যে তোমরা ভালো, বিবেচক ও সংযত হবে, নগরের মাঝখানে বাস করেই।",
"kc7ddce00": "সন্ত জন ক্রিসোস্তম, মথির উপর উপদেশ ৭ &middot; অনু. George Prevost &middot; <a href=\"/library#work=chrysostom-homilies-matthew\">গ্রন্থাগারে পড়ুন</a>",
"k99a23dda": "আর রোমীয়দের উপর তিনি এই ভাবনাকে যে সাধারণ জীবন আজ্ঞাগুলির ভুল ঠিকানা, বিশ্বাসের বিরুদ্ধে অভিযোগ বলে ধরেন, তার বর্ণনা বলে নয়:",
"k91017238": "কারণ যদি নগরের মাঝে বাসকারীর পক্ষে শিষ্য হওয়া সম্ভব না হয়, তবে তা এই জীবনরীতির বিরুদ্ধে গুরুতর অভিযোগ, অর্থাৎ এই যে আমাদের নগর ছেড়ে মরুভূমিতে ছুটে যেতে হবে। কিন্তু আমাকে এমন একজন দেখাও যাঁর স্ত্রী আছে, সন্তান আছে, পরিবার আছে, এবং তবু যিনি প্রজ্ঞা খোঁজেন। তবে এই সব বিষয়ে আমরা কী বলব? আমাদের কি মাথা নত করে লজ্জিত হওয়া উচিত নয়? কারণ খ্রিষ্ট আমাদের এমন আজ্ঞা দেননি; বরং কী দিয়েছেন? তোমাদের আলো মানুষের সামনে উজ্জ্বল হোক, পর্বত, মরুভূমি, প্রান্তর ও নির্জন স্থান নয়।",
"kafb2fb07": "সন্ত জন ক্রিসোস্তম, রোমীয়ের উপর উপদেশ ২৬ &middot; অনু. J. B. Morris ও W. H. Simcox &middot; <a href=\"/library#work=chrysostom-homilies-romans\">গ্রন্থাগারে পড়ুন</a>",
"ke1ee6e3e": "ঠিক পরের বাক্যেই তিনি সতর্ক থাকেন যেন সন্ন্যাসীদের হেয় করছেন বলে পড়া না হয়: তিনি বলেন যে তিনি বলছেন \"যাঁরা পর্বত গ্রহণ করেছেন তাঁদের নিন্দা করে নয়, বরং যাঁরা নগরে বাস করেন তাঁদের জন্য বিলাপ করে, কারণ তাঁরা সেখান থেকে সদ্গুণ তাড়িয়ে দিয়েছেন।\" সন্ন্যাসী নিজের ইচ্ছা এক প্রবীণের হাতে তুলে দেন। সাধারণ বিশ্বাসীকেও সেই একই জিনিস তুলে দেওয়ার জন্য দেওয়া হয়েছে - বিবাহে, এমন কাজে যা সে বেছে নেয়নি, একটি সংসার যে ধৈর্য দাবি করে তাতে - এবং তা তার কাছে এমন রূপে চাওয়া হয় যা কোনো নিয়ম আগে থেকে ছাপতে পারে না।",
"ka438020e": "উপবাস, স্বীকারোক্তি, এবং প্রস্তুতির বাকি অংশ",
"k67ac3841": "প্রস্তুতি কেবল প্রার্থনা নয়। বুধ ও শুক্রবারের উপবাস তার প্রাচীনতম অংশ, এবং তা দিদাখের সেই একই অধ্যায়ে আছে যা প্রার্থনার নিয়ম দেয়:",
"ke069eea2": "কিন্তু তোমাদের উপবাস যেন ভণ্ডদের সঙ্গে না হয়; কারণ তারা সপ্তাহের দ্বিতীয় ও পঞ্চম দিনে উপবাস করে; তোমরা বরং চতুর্থ দিনে ও প্রস্তুতির দিনে (শুক্রবার) উপবাস করো। আর ভণ্ডদের মতো প্রার্থনাও করো না, বরং প্রভু তাঁর সুসমাচারে যেমন আজ্ঞা দিয়েছেন, তেমনি প্রার্থনা করো: হে আমাদের স্বর্গস্থ পিতা...",
"k4e4ee152": "এই অনুচ্ছেদের সতর্কবাণী দুই অর্ধেকের উপরেই বর্তায়: উপবাস না করার উপরে নয়, বরং <em>ভণ্ডদের মতো</em> উপবাস করার উপরে, এবং প্রার্থনা না করার উপরে নয়, বরং <em>ভণ্ডদের মতো</em> প্রার্থনা করার উপরে। দিদাখে দুটি নিয়মই এক নিঃশ্বাসে দেয় এবং প্রত্যেকটিকে একইভাবে সীমিত করে।",
"k901f0415": "প্রভুভোজের আগে স্বীকারোক্তি কিছু ঐতিহ্যে প্রত্যাশিত এবং অন্যগুলিতে নয়, আর এই পার্থক্য পুরোনো, শিথিলতার বিষয় নয়। এটি স্পষ্ট করে বলা মূল্যবান, কারণ যিনি এক ঐতিহ্যে প্রস্তুত হতে শিখেছেন এবং পরে অন্য ঐতিহ্যের মণ্ডলীতে গিয়ে পড়েছেন, তিনি সহজেই প্রথার পার্থক্যকে নিজের উপরে বিচার বলে ধরে নিতে পারেন।",
"k345e3232": "<strong>স্লাভ মণ্ডলীগুলিতে</strong> - রুশ, বিদেশের রুশ, আমেরিকার অর্থোডক্স মণ্ডলী, ইউক্রেনীয়, সার্বীয় - সাধারণত প্রতিটি প্রভুভোজের আগে স্বীকারোক্তি প্রত্যাশিত। প্রস্তুতিতে প্রথা অনুসারে তিনটি কানন থাকে - ত্রাণকর্তার উদ্দেশে, ঈশ্বরজননীর উদ্দেশে ও রক্ষক দূতের উদ্দেশে - এবং প্রায়ই পরমমধুর প্রভু যিশুর আকাথিস্ত, প্রস্তুতির প্রার্থনার অতিরিক্ত; আর আগের সন্ধ্যার রাত্রি-জাগরণ বা সন্ধ্যা-উপাসনায় উপস্থিতি প্রস্তুতিরই অংশ বলে প্রত্যাশিত, আলাদা ভক্তি হিসাবে নয়।",
"k3c46f09c": "<strong>গ্রিক, আন্তিওখীয় ও রোমানীয় চর্চায়</strong> স্বীকারোক্তি প্রায়ই প্রভুভোজ থেকে আলাদা এবং আধ্যাত্মিক পিতার নির্ধারিত ব্যবধানে পালিত হয়, প্রায়ই চারটি উপবাসকালে। প্রস্তুতি বলতে প্রায়ই প্রস্তুতির প্রার্থনাই বোঝায়, কাননগুলি ও আকাথিস্তের পূর্ণ সমাহার নয়, এবং সন্ধ্যার উপাসনায় জোরালোভাবে উৎসাহ দেওয়া হয় কিন্তু তা গ্রহণের শর্ত করা হয় না।",
"kbf226744": "দুটিই সমগ্র স্থানীয় মণ্ডলীর প্রতিষ্ঠিত চর্চা, এবং প্রত্যেকটি সেই মণ্ডলীর যাজকবর্গের পরিচালনায় পালিত হয়। এখানে একজনের নিয়ম আসে তাঁর নিজের আধ্যাত্মিক পিতার কাছ থেকে, সেই বর্ণনা থেকে নয় যা তিনি ঘটনাক্রমে প্রথমে পড়েছেন।",
"k7edee590": "পরিমাণ সম্বন্ধে শেষ কথা",
"k95bf9581": "নিয়ম আছে এই কারণে যে আমরা একদিকে আলস্যের কাছে হার না মানি, আর অন্যদিকে নিজেদের সামর্থ্যের বাইরে না ঠেলি। নির্জনবাসী সন্ত থেওফান শেখাতেন যে পথের দুটি খাদ আছে: ডানদিকে জ্ঞানহীন উদ্যম; বাঁদিকে আলস্য। বাড়াবাড়ি শুরু করা মানুষকে ব্যর্থ হলে ক্লান্তি ও হতাশায় নিয়ে যায়, আর সফল হলে অহংকারে। সন্ত ইগ্নাতি ব্রিয়ানচানিনভ লিখেছিলেন যে নিয়ম তোমার জন্য আছে; তুমি নিয়মের জন্য নও, বরং প্রভুর জন্য বাঁচো, এবং তোমাকে বিচারের স্বাধীনতা রক্ষা করতে হবে।",
"kd192a6bd": "অল্প দিয়ে শুরু করো। অনেক প্রার্থনা তাড়াহুড়ো করে পার করার চেয়ে অল্প কয়েকটি মনোযোগ দিয়ে বলা ভালো। যদি তোমার আধ্যাত্মিক পিতা থাকেন, তবে তিনি যে নিয়ম দেন তাই পালন করো এবং তাঁর আশীর্বাদ ছাড়া কিছু বদলিও না; যদি এখনও না থাকেন, তবে নিজের সামর্থ্য অনুসারে পরিমিত নিয়ম পালন করো এবং এমন পিতা খোঁজো। কোনো বই বা কোনো পৃষ্ঠাই খ্রিষ্টে জীবন্ত পিতার স্থান নিতে পারে না।",
"kb6eb659b": "নির্জনবাসী সন্ত থেওফান, প্রার্থনার নিয়ম, এবং সন্ত ইগ্নাতি (ব্রিয়ানচানিনভ)-এর প্রার্থনার নিয়ম সংক্রান্ত রচনা থেকে &middot; <a href=\"/#guide\">নির্দেশিকাতেও</a>",
"keda0cc2f": "এই সাইটে এমন কিছুই নেই যা কাউকে ওজন করার দাঁড়িপাল্লা। এটি একটি গ্রন্থাগার এবং একটি পঞ্জিকা।",
"kc89cd31d": "প্রার্থনার নিয়ম হল নির্দিষ্ট সময়ে রক্ষিত প্রার্থনার একটি নির্দিষ্ট পরিমাণ। এই পৃষ্ঠা জানায়, পরিমাণ সম্পর্কে মণ্ডলীর উৎসগুলি কী বলে, এবং নিয়ম সাধারণত কী কী রূপ নেয়।",
"k36c2948e": "<strong>প্রথমে এটি পড়ুন।</strong> আপনি যে নিয়ম রক্ষা করেন তা আপনার আধ্যাত্মিক পিতা স্থির করেন, আপনার শক্তি ও পরিস্থিতি অনুসারে। এখানে যা মুদ্রিত তা উত্তরাধিকার, কাউকে মাপার মানদণ্ড নয়। যিনি দিনে তিনবার প্রভুর প্রার্থনা বলেন এবং অন্তর থেকে বলেন, তিনি সেই নিয়মই রক্ষা করছেন যা মণ্ডলী প্রথম শতাব্দীতে দিয়েছিল।",
"k530f73b4": "নিয়ম কোথা থেকে এসেছে",
"kc776efc1": "দুই অধ্যায় আগে সেই একই নথি পরিমাণটি জানায়, এবং এ বিষয়ে মণ্ডলীর লেখা এটিই প্রাচীনতম:",
"k81f4ff1a": "প্রার্থনা-পুস্তকে যা কিছু আছে সবই পরে এসেছে। আর নির্দিষ্ট প্রহরের নিয়ম প্রার্থনার সেবা করে, তাকে নিঃশেষ করে না: প্রেরিতের <em>অবিরত প্রার্থনা কর</em> (১ থিষলনীকীয় ৫:১৭) হল বৃহত্তর পরিমাপ, আর সাধু যোহন কাসিয়ান, মিশরের পিতৃগণকে লিপিবদ্ধ করতে গিয়ে, তা কঠোরভাবেই বলেন।",
"k071c623f": "নিয়ম যে রূপগুলি নেয়",
"k28364d47": "এইগুলি সাধারণ গৃহীর নিয়মের প্রচলিত রূপ, সাজানো হয়েছে প্রত্যেকটি দিনের কতখানি চায় সেই অনুসারে। এটি ওঠার সিঁড়ি নয়: প্রথমটিই সেই বস্তু যাকে হেসিকাস্ট পিতৃগণ সমগ্র প্রার্থনা বলে বর্ণনা করেন, এবং যা সবচেয়ে দূর অবধি এগিয়ে যাওয়া ব্যক্তিদের সমস্ত লিখিত বস্তুর পরিবর্তে দেওয়া হয়। <strong>কোনটি আপনার ক্ষেত্রে প্রযোজ্য, তা আপনার আধ্যাত্মিক পিতাকে জিজ্ঞাসা করার বিষয়।</strong>",
"kf8b6b4bc": "নির্দিষ্ট সময় ছাড়া প্রার্থনা &middot; যখন সময় নেই, পুস্তক নেই, নীরবতাও নেই",
"k491be6c4": "<em>প্রভু যীশু খ্রীষ্ট, ঈশ্বরের পুত্র, আমার প্রতি, এই পাপীর প্রতি, দয়া কর।</em> যেখানে এটিও বেশি, সেখানে পিতৃগণ সংক্ষিপ্ততর রূপ অনুমোদন করেন - <em>প্রভু যীশু খ্রীষ্ট, আমার প্রতি দয়া কর</em>, অথবা কেবল <em>প্রভু, দয়া কর</em>। এতে পুস্তক লাগে না, দাঁড়ানো লাগে না, স্বরও লাগে না, এবং কাজের একটি গোটা দিন জুড়ে একে বহন করা যায়। এটি প্রথমে রয়েছে কারণ এটি সমস্ত পরিস্থিতিতেই টিকে থাকে, এই কারণে নয় যে এখানে যা কিছু আছে তার মধ্যে এটি ক্ষুদ্রতম।",
"k2d14e1b1": "নির্দিষ্ট সময়ে একটি সংক্ষিপ্ত নিয়ম &middot; দিদাখে",
"k25c1035a": "নির্দিষ্ট প্রার্থনার সঙ্গে দিনভর চলা প্রার্থনা যুক্ত &middot; যাঁদের কাজ এর বেশির জন্য অবকাশ রাখে না তাঁদের জন্য",
"k5cacd522": "সাধু সেরাফিম এটি সেই শ্রমিক ও গৃহস্থদের দিয়েছিলেন যাঁরা পূর্ণতর প্রার্থনাগুলি রক্ষা করতে পারতেন না, এবং তিনি একে এমন ছাড় বলে গণ্য করেননি যা থেকে বড় হয়ে বেরিয়ে আসতে হয়।",
"kc0703990": "ওঠার সময় প্রভাতের প্রার্থনা এবং ঘুমের আগে সন্ধ্যার প্রার্থনা, তাড়াহুড়ো না করে মনোযোগের সঙ্গে বলা। সাধু থেওফান নির্জনবাসী এগুলিকে সদ্য আরম্ভ করা গৃহীর জন্য সম্পূর্ণরূপে যথেষ্ট বলে গণ্য করতেন।",
"k030dfcd7": "উপাসনার দৈনিক চক্র &middot; যেখানে দিন তা অনুমোদন করে",
"k129ba7c3": "দিনভর সংক্ষিপ্ত উপাসনাগুলি, প্রথম প্রহর থেকে রাত্রির প্রার্থনা পর্যন্ত। দিদাখের দিনে তিনবারের প্রার্থনা এই চক্রের বীজ; পূর্ণ প্রহরগুলি প্রহর-পুস্তকে দেওয়া আছে।",
"k6ca85803": "উপলক্ষের নিয়ম &middot; রহস্যসমূহ গ্রহণের আগে",
"kc26de5d2": "ভ্রমণ, অসুস্থতা, রাতের কাজ, ছোট সন্তান, শোক ও ক্লান্তি - সবই নিয়ম ভাঙে। উপরের দুটি পাঠ এর সঙ্গে সরাসরি সম্পর্কিত। দিদাখে তার নিয়মকে সব-অথবা-কিছুই-নয় হিসেবে উপস্থাপন করে না: যেখানে সমস্ত জোয়াল বহন করা যায় না, \"যা তুমি পার, তা-ই কর\"। আর কাসিয়ান তাঁদের তিরস্কার করেন যাঁরা কেবল হাঁটু পাতার সময় দিয়েই নিজেদের প্রার্থনা গণনা করেন - যা সেই সময়ের বাইরের প্রার্থনাকে গণনার ভিতরে আনে, বাইরে নয়।",
"k892d0484": "প্রস্তুতির অনুক্রম সত্যিকারের একটি মঙ্গল এবং সত্যিকারের একটি উত্তরাধিকার। কিন্তু মানুষকে গ্রহণের যোগ্য করে তোলে তা নয়। সাধু যোহন ক্রিসোস্তম কত ঘন ঘন ও কতখানি, এই প্রশ্নটি তুলে নেন এবং সেই ভাষায় উত্তর দিতে অস্বীকার করেন:",
"k74472bee": "তিনি যে মানদণ্ডের নাম করেন তা বিবেকের অবস্থা, কোনো সংখ্যা নয়। সাধু যোহন কাসিয়ান অপর অর্ধেকটি এমন এক অধ্যায়-শিরোনামের অধীনে আলোচনা করেন যা কথাটি স্পষ্ট বলে: <em>যদিও আমরা স্বীকার করি যে আমরা পাপহীন হতে পারি না, তথাপি প্রভুর সহভাগিতা থেকে নিজেদের সরিয়ে রাখা আমাদের উচিত নয়।</em>",
"k89f08ec2": "অযোগ্যতার অনুভব থেকে বিরত থাকাই, তিনি যুক্তি দেন, বৃহত্তর ধৃষ্টতা: যে যোগ্য না হওয়া পর্যন্ত বিরত থাকে, সে ধরে নেয় যে অন্য কোনো দিন সে যোগ্য হত। রহস্যসমূহ শুচিদের জন্য পুরস্কার নয়, বরং তাঁরই ভাষায়, গ্রহণ করার দ্বারাই আমাদের সাধু ও শুচি করে তুলত।",
"ke31bdf96": "এটি মানদণ্ড নামিয়ে আনা নয়। এটিই মানদণ্ড, আর মণ্ডলী তা প্রত্যেক নিকটে আসা ব্যক্তির মুখে স্থাপন করে:",
"kfbddc832": "প্রেরিতের নিজের কথা হল <em>খ্রীষ্ট যীশু পাপীদের পরিত্রাণ করতে জগতে এসেছিলেন, যাঁদের মধ্যে আমি প্রধান</em>, আর মণ্ডলী সেগুলি পত্রের মধ্যেই ছেড়ে রাখেনি: সে সেগুলি উপাসনায় গ্রহণ করেছে এবং প্রত্যেক সহভাগীকে দিয়েছে উত্তম পুরুষে বলার জন্য, সেই দিনেই যেদিন সে গ্রহণ করে। সাধু তাঁরাই যাঁরা সেই বাক্যটি বলেছেন এবং অন্তর থেকে বলেছেন, তাঁরা নন যাঁরা এমন স্থানে পৌঁছেছেন যেখানে তা আর প্রযোজ্য থাকেনি।",
"kdc0a783e": "<strong>ঐতিহ্য যেগুলির নাম করে</strong> সেগুলি হল এমন বিবেক যা অনুতপ্ত নয় এমন পাপে বিশ্রাম নেয় না, প্রতিবেশীর সঙ্গে শান্তি, সহভাগিতার আগের উপবাস, এবং স্বীকারোক্তির বিষয়ে আধ্যাত্মিক পিতার প্রতি আনুগত্য।",
"keeb5d497": "<strong>সহভাগিতার আগের উপবাস প্রথাগত নয়, ক্যাননসম্মত।</strong> ৪১৯ সালের আফ্রিকান বিধান তা দাবি করত এবং বছরে একটি ব্যতিক্রম অনুমোদন করত; ত্রুল্লোর মহাসভা সেই ক্যাননটি গ্রহণ করে ব্যতিক্রমটি তুলে দেয়:",
"k718a2fab": "কিন্তু যেহেতু যথাযথ পালন ত্যাগ করার মতো কিছুই আমাদের চালিত করে না, আমরা স্থির করি যে প্রেরিতিক ও পিতৃ-ঐতিহ্য অনুসরণ করা হবে, এবং নির্ধারণ করি যে মহা-উপবাসের শেষ সপ্তাহের পঞ্চম দিনে উপবাস ভঙ্গ করা এবং এইভাবে সমগ্র মহা-উপবাসকে অসম্মান করা সঙ্গত নয়।",
"k2426bb65": "ক্যাননগুলি যা দাবি করে তা হল উপবাস। পূর্ববর্তী মধ্যরাত থেকে তা গণনা করাই সেই প্রথা যা একে বহন করে। যেখানে ধর্মানুষ্ঠান সন্ধ্যায় সম্পন্ন হয় - পূর্বপবিত্রীকৃত দানের, এবং জন্মোৎসব, থিওফানি, মহাবৃহস্পতিবার ও মহাশনিবারের ধর্মানুষ্ঠান - সেখানে সময়সীমা বিশপ নির্ধারণ করেন, মধ্যরাত থেকে গোনা হয় না। যে ওষুধ অবশ্যই নিতে হয়, অসুস্থতা, গর্ভাবস্থা, শৈশব ও অতিবার্ধক্য - এসবের নিষ্পত্তি আধ্যাত্মিক পিতা করেন। জিজ্ঞাসা করা রেহাই পাওয়ার সমান নয়, আর এর কোনোটিই পানপাত্র থেকে দূরে থাকার কারণ নয়।",
"ka41be440": "তিনি মরুভূমিকে বিধান বানাতে অস্বীকার করেন - \"আমি তোমাদের জন্য এই বিধান দিচ্ছি না যে পর্বত ও মরুভূমি অধিকার কর, বরং এই যে নগরের মধ্যে বাস করেই ভাল, সহানুভূতিশীল ও শুচি হও\" - এবং তিনি সতর্ক থাকেন যেন সন্ন্যাসীদের হেয় করছেন বলে পঠিত না হন, বলেন যে তিনি বলছেন \"যাঁরা পর্বত গ্রহণ করেছেন তাঁদের গালি দিয়ে নয়, বরং যাঁরা নগরে বাস করেন তাঁদের জন্য বিলাপ করে, কারণ তাঁরা সেখান থেকে সদ্‌গুণকে বিতাড়িত করেছেন\"। সন্ন্যাসী নিজের ইচ্ছা এক প্রবীণের হাতে সমর্পণ করেন। গৃহীকেও সমর্পণ করার জন্য সেই একই বস্তু দেওয়া হয়েছে - বিবাহে, এমন কাজে যা সে বেছে নেয়নি, এক সংসার যে ধৈর্য দাবি করে তাতে - এবং তা তার কাছে এমন রূপে চাওয়া হয় যা কোনো নিয়ম আগে থেকে ছাপতে পারে না।",
"ke5795f78": "উপবাস ও স্বীকারোক্তি",
"k6602f295": "প্রস্তুতি কেবল প্রার্থনা নয়। বুধবার ও শুক্রবারের উপবাস তার প্রাচীনতম অংশ, এবং তা দিদাখের সেই একই অধ্যায়ে রয়েছে যা প্রার্থনার নিয়ম দেয় - যা উভয় অর্ধকেই একইভাবে সীমিত করে, সতর্ক করে উপবাস বা প্রার্থনা না করার বিরুদ্ধে নয়, বরং এর যেকোনো একটিকে <em>ভণ্ডদের মতো</em> করার বিরুদ্ধে।",
"k78388bd9": "সহভাগিতার আগে স্বীকারোক্তি কোনো কোনো ঐতিহ্যে প্রত্যাশিত এবং অন্যগুলিতে নয়, আর এই পার্থক্য শৈথিল্যের বিষয় নয়, বরং বহু পুরনো। যিনি এক ঐতিহ্যে প্রস্তুত হতে শিখেছেন এবং পরে অন্যটির মণ্ডলীতে গিয়ে পড়েন, তিনি সহজেই প্রথার পার্থক্যকে নিজের উপর বিচার বলে ধরে নিতে পারেন।",
}
